#!/usr/bin/env node
/* Regenerates js/gallery-manifest.js from public/images/gallery/<folder>.
   Run via scripts/optimize-images.sh (or directly: node scripts/build-gallery-manifest.js). */
"use strict";
const fs = require("fs");

const folders = ["whare", "whenua", "tangata"];
const out = {};
for (const d of folders) {
  const dir = `public/images/gallery/${d}`;
  out[d] = fs
    .readdirSync(dir)
    .filter((f) => /\.(jpe?g|png|gif|webp)$/i.test(f) && !f.startsWith("."))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
}

const js =
  "/* AUTO-GENERATED by scripts/optimize-images.sh — do not edit by hand.\n" +
   "   Add photos to public/images/gallery/<folder>/ then rerun the script. */\n" +
  "window.GALLERY_MANIFEST = " +
  JSON.stringify(out, null, 2) +
  ";\n";

fs.writeFileSync("js/gallery-manifest.js", js);
console.log(
  "js/gallery-manifest.js written:",
  folders.map((d) => `${d}=${out[d].length}`).join(", ")
);